"""CodeBench (iOS): auto-show a generated .blend in the editor preview box.

Loaded automatically at Blender startup. It registers a ``save_post`` handler so
that whenever a script saves a ``.blend`` (``bpy.ops.wm.save_as_mainfile``), the
scene is turned into an INTERACTIVE WebGL 3D viewer (orbit / pinch-zoom / pan)
and shipped to CodeBench's native preview pane — which renders the HTML in a
``WKWebView``. The user writes no preview code at all: generating a ``.blend``
just makes a live, draggable model appear.

A Cycles (CPU) still-render is also produced and embedded behind a
"Rendered ⟷ 3D" toggle, so the photoreal image is one tap away. If geometry
extraction fails for any reason, we fall back to shipping just the still image.

If the scene has no camera/light a temporary one is added so the render isn't
black. Failures are swallowed (e.g. when not running inside CodeBench).
"""

import os
import sys
import tempfile
import time

import bpy
from bpy.app.handlers import persistent

_CB_CAM = "CB_PreviewCamera"
_CB_SUN = "CB_PreviewSun"
# Guard against re-entrancy: rendering must not retrigger this handler.
_CB_BUSY = False


def _inline_image_dir():
    d = os.path.join(tempfile.gettempdir(), "codebench_inline_images")
    os.makedirs(d, exist_ok=True)
    return d


def _render_still(scene):
    """Render a small Cycles still for the 'Rendered' toggle. Returns the PNG
    path, or None if rendering failed. Best-effort — never raises."""
    try:
        # Ensure the scene is lit + framed, else the render is black.
        if scene.camera is None:
            cam = scene.objects.get(_CB_CAM)
            if cam is None:
                cam_data = bpy.data.cameras.new(_CB_CAM)
                cam = bpy.data.objects.new(_CB_CAM, cam_data)
                scene.collection.objects.link(cam)
                cam.location = (7.0, -7.0, 5.0)
                cam.rotation_euler = (0.9926, 0.0, 0.7854)
            scene.camera = cam
        if not any(o.type == 'LIGHT' for o in scene.objects):
            if scene.objects.get(_CB_SUN) is None:
                sun_data = bpy.data.lights.new(_CB_SUN, 'SUN')
                sun_data.energy = 4.0
                sun = bpy.data.objects.new(_CB_SUN, sun_data)
                scene.collection.objects.link(sun)
                sun.location = (4.0, -4.0, 8.0)
        try:
            scene.render.engine = 'CYCLES'
            scene.cycles.samples = 16
        except Exception:
            pass  # Cycles unavailable — fall back to whatever engine is set.
        scene.render.image_settings.file_format = 'PNG'
        scene.render.resolution_x = 640
        scene.render.resolution_y = 480
        out = os.path.join(_inline_image_dir(), "blend_%d.png" % int(time.time() * 1000))
        scene.render.filepath = out
        bpy.ops.render.render(write_still=True)
        return out if os.path.isfile(out) else None
    except Exception as ex:
        sys.stderr.write("[codebench_blend_preview] render skipped: %s\n" % ex)
        return None


@persistent
def _codebench_render_preview(*_args):
    global _CB_BUSY
    if _CB_BUSY:
        return

    _CB_BUSY = True
    try:
        # Use `bpy.data` not `bpy.context` — inside a save_post handler the
        # context is restricted and `bpy.context.scene` is often None.
        scene = bpy.data.scenes[0] if bpy.data.scenes else None
        if scene is None:
            return

        name = os.path.basename(bpy.data.filepath) or "untitled.blend"
        if os.environ.get("CB_BLEND_NO_RENDER"):
            png = None          # opt-out of the still render (faster saves)
        else:
            png = _render_still(scene)

        # Build the interactive WebGL viewer (with the still embedded for the
        # Rendered toggle). Falls back to the still image if extraction fails.
        html = None
        try:
            import codebench_blend_view
            html = codebench_blend_view.build_view(scene, render_png_path=png, title=name)
        except Exception as ex:
            sys.stderr.write("[codebench_blend_preview] viewer build failed: %s\n" % ex)

        try:
            blend_sz = os.path.getsize(bpy.data.filepath) if bpy.data.filepath else 0
        except Exception:
            blend_sz = 0

        if html:
            codebench_blend_view.emit(html)
            print("✓ Blender: generated %s (%d bytes) → interactive 3D preview "
                  "(drag to orbit · pinch to zoom)" % (name, blend_sz), flush=True)
        elif png:
            # Fallback: ship the still through the same channels as before.
            print("[plot saved] %s" % png, flush=True)
            try:
                sys.modules["__main__"].__codebench_plot_path = png
            except Exception:
                pass
            try:
                import codebench_inline
                codebench_inline.show_png(png, caption=name)
            except Exception:
                pass
            print("✓ Blender: generated %s (%d bytes) + rendered preview"
                  % (name, blend_sz), flush=True)
        else:
            sys.stderr.write("[codebench_blend_preview] nothing to preview for %s\n" % name)
    except Exception as ex:
        sys.stderr.write("[codebench_blend_preview] %s\n" % ex)
    finally:
        _CB_BUSY = False


def register():
    if _codebench_render_preview not in bpy.app.handlers.save_post:
        bpy.app.handlers.save_post.append(_codebench_render_preview)


def unregister():
    if _codebench_render_preview in bpy.app.handlers.save_post:
        bpy.app.handlers.save_post.remove(_codebench_render_preview)
